import{_ as e,a as i,c as a,ac as t}from"./chunks/framework.BSuaGltH.js";const k=JSON.parse('{"title":"CentOS 7 与 Redis 4.0.1 安装笔记","description":"CentOS 7 包安装、Redis 4.0.1 源码编译及旧 Windows 服务命令。","frontmatter":{"title":"CentOS 7 与 Redis 4.0.1 安装笔记","description":"CentOS 7 包安装、Redis 4.0.1 源码编译及旧 Windows 服务命令。","sources":[{"repository":"jekyall_blog","file":"_posts/DataStorage/redis/not/redis centos 7.md","date":"Sat Jan 26 2019 12:48:54 GMT+0800 (中国标准时间)"},{"repository":"jekyall_blog","file":"_posts/DataStorage/redis/not/RedisInstall.md"}],"showdocs":{"topics":[{"id":"redis","title":"Redis","link":"/topics/redis/"}],"kind":"数据与原子性","scope":"historical","audience":"general","group":"数据库与存储","summary":"CentOS 7 包安装、Redis 4.0.1 源码编译及旧 Windows 服务命令。","status":"active","related":[{"title":"Redis 操作与命令","link":"/middleware/redis/plus/ecosystem/redis-general-general","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 配置","link":"/middleware/redis/plus/subjects/redis-config","kind":"数据与原子性","scope":"historical","audience":"general"},{"title":"Redis 数据类型命令速查","link":"/middleware/redis/plus/subjects/redis-data-cmd","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 完整实践：Lua 原子限额与可重试 CLI","link":"/middleware/redis/plus/practice/quota","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 游戏与通用后端场景","link":"/middleware/redis/pro/practice/game-scenarios","kind":"完整实践","scope":"general","audience":"general"}],"prev":false,"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":false},"headers":[],"relativePath":"middleware/redis/plus/subjects/redis-centos-7.md","filePath":"middleware/redis/plus/subjects/redis-centos-7.md"}'),l={name:"middleware/redis/plus/subjects/redis-centos-7.md"};function n(d,s,r,p,h,o){return i(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="centos-7-与-redis-4-0-1-安装笔记" tabindex="-1">CentOS 7 与 Redis 4.0.1 安装笔记 <a class="header-anchor" href="#centos-7-与-redis-4-0-1-安装笔记" aria-label="Permalink to &quot;CentOS 7 与 Redis 4.0.1 安装笔记&quot;">​</a></h1><blockquote><p>这是 CentOS 7、Redis 4.0.1 及旧 Windows 移植版的安装记录。下方保留当时的命令与配置；端口绑定、认证方式和系统服务均需按目标环境重新确认。</p></blockquote><p><span id="redis-安装"></span></p><p>当前入门请从<a href="/middleware/redis/base/basic/start">Redis起步与连接</a>开始。以下两条路线保留历史背景，不能混用包管理器安装路径与源码安装路径；本轮未执行命令。</p><h2 id="历史路线一-centos包安装" tabindex="-1">历史路线一：CentOS包安装 <a class="header-anchor" href="#历史路线一-centos包安装" aria-label="Permalink to &quot;历史路线一：CentOS包安装&quot;">​</a></h2><p>原记录先添加EPEL，再用yum安装，属于包安装而不是源码安装；包版本由当时仓库决定，不保证是4.0.1。先确认仓库和维护策略，再评估旧命令：</p><div class="language-shell vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> epel-release</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis</span></span></code></pre></div><p>原配置位置为 <code>/etc/redis.conf</code>，应先核对服务实际加载的文件。原笔记建议注释 <code>bind 127.0.0.1</code> 以便远程连接；这会扩大网络暴露，不能当成通用安装步骤。保留本地绑定，远程访问由部署拥有者确认监听地址、网络限制与认证。旧 <code>requirepass</code> 的口令必须自行设置，不使用文中示例口令。</p><h3 id="服务管理" tabindex="-1">服务管理 <a class="header-anchor" href="#服务管理" aria-label="Permalink to &quot;服务管理&quot;">​</a></h3><p>以下只用于由系统服务管理的安装：</p><div class="language-shell vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis.service</span></span></code></pre></div><p>启动、停止分别使用 <code>systemctl start/stop redis.service</code>；开机启用、禁用分别使用 <code>systemctl enable/disable redis.service</code>，需要相应权限。它们不管理下一节从源码手动启动的进程。</p><p>原笔记参考站点：Linux CentOS 7安装Redis服务器教程，www.centos.bz；原文未保留具体文章URL。</p><h2 id="历史路线二-redis-4-0-1源码编译" tabindex="-1">历史路线二：Redis 4.0.1源码编译 <a class="header-anchor" href="#历史路线二-redis-4-0-1源码编译" aria-label="Permalink to &quot;历史路线二：Redis 4.0.1源码编译&quot;">​</a></h2><p>前置为可用的编译工具与make。下列版本仅作历史对照，下载与编译未在本轮执行：</p><div class="language-shell vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://download.redis.io/releases/redis-4.0.1.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -zxvf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis-4.0.1.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis-4.0.1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span></span></code></pre></div><p>解压目录与压缩包版本保持一致。<code>make install</code> 会把程序安装到所选前缀（原记录使用 <code>/usr/local/bin</code>），写入权限和安装前缀需先确认。不要与yum安装的程序混淆，可先核对 <code>command -v redis-server</code>。</p><div class="language-shell vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-server</span></span></code></pre></div><p>该命令以前台方式启动。另开终端，用 <code>redis-cli</code> 连接；本地默认端口且没有认证时可请求关闭：</p><div class="language-shell vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shutdown</span></span></code></pre></div><p>原记录的 <code>server-cli</code> 是工具名拼写错误。若修改了地址、端口或认证，应使用与该实例匹配的连接参数。配置中的 <code>daemonize no</code> 改为 <code>yes</code> 会后台运行，但已有服务管理器时应遵循其进程管理方式，不把两套方法叠加。</p><h3 id="卸载边界" tabindex="-1">卸载边界 <a class="header-anchor" href="#卸载边界" aria-label="Permalink to &quot;卸载边界&quot;">​</a></h3><p>原记录给出 <code>rm -rf /usr/local/bin/redis*</code> 和删除解压目录的命令，不能作为通用卸载方案：先停止目标实例并备份配置和数据，包安装由包管理器处理；源码安装则按确认过的安装清单移除具体文件，避免通配符删除其他版本。删除程序不等于清理服务、配置与数据。</p><h2 id="windows-redis-加入开机自启" tabindex="-1">windows redis 加入开机自启 <a class="header-anchor" href="#windows-redis-加入开机自启" aria-label="Permalink to &quot;windows redis 加入开机自启&quot;">​</a></h2><p>本节是旧Windows移植版的服务命令，不能套用于Linux源码版；配置文件必须已存在，安装服务需相应权限：</p><div class="language-shell vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --service-install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis.windows-service.conf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loglevel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verbose</span></span></code></pre></div><p>原文另一行使用了长横线 <code>–service-install</code>，已统一为两个ASCII连字符。<code>redis-cli.exe</code>用于连接；旧记录里的 <code>AUTH root</code>、<code>CONFIG SET requirepass root</code>、<code>AUTH 123456</code>是先后变更口令的演示，不能一起复制，也不能用作实际口令。先确认所用Windows发行版的维护状态与服务文档，再由环境拥有者决定是否继续采用。本轮未安装服务或修改口令。</p>`,27)])])}const g=e(l,[["render",n]]);export{k as __pageData,g as default};
